/** Presentation only: no catalog goal is imported or generated by displaying artwork. */
import { useState } from "react";
import data from "../data/catalogPresentation.json";
import type { SourceReference } from "../lib/api";

type Artwork = { image?: string; thumbnail?: string; width?: number; height?: number; thumbnailWidth?: number };
type GoalVisual = Artwork & { title: string; description: string; goalId: string; category: string; age: string; alt: string; emoji: string; contexts: string[] };
type CategoryVisual = Artwork & { title: string; track: string };
const goals: Record<string, GoalVisual> = data.goals;
const categories: Record<string, CategoryVisual> = data.categories;
const byGoalId = Object.fromEntries(Object.values(goals).map((goal) => [goal.goalId, goal]));
export const friendly = (value: string) => value.replace(/[_-]/g, " ");
export const supportLabel = (value: string) => ({ adult_scaffolded: "Grown-up support", adult_together: "Do it together", child_led_with_checkin: "Child leads, grown-up checks in", shared_planning: "Plan it together" }[value] ?? friendly(value));

/** Saved goals can retain their public presentation after a conversation is reset. */
export function catalogVisualForGoal(goalId: string) {
  const goal = byGoalId[goalId];
  return goal ? { ...goal, categoryTitle: categories[goal.category]?.title ?? friendly(goal.category), track: categories[goal.category]?.track ?? "development" } : undefined;
}

export function catalogVisual(source: SourceReference) {
  const goal = goals[source.source_id];
  const category = categories[source.category_id];
  return { ...goal, categoryTitle: category?.title ?? friendly(source.category_id), track: category?.track ?? "development", image: goal?.image ?? category?.image, width: goal?.width ?? category?.width, height: goal?.height ?? category?.height, emoji: goal?.emoji ?? "🌱" };
}

/** Use the original 512px illustration above thumbnail size, including high-density screens. */
function CatalogArtwork({ visual, sizes, alt }: { visual: Artwork & { emoji?: string }; sizes: string; alt: string }) {
  const [failed, setFailed] = useState(false);
  if (!visual.image || failed) return <span aria-hidden="true">{visual.emoji ?? "🌱"}</span>;
  const srcSet = visual.thumbnail && visual.thumbnailWidth && visual.width
    ? `${visual.thumbnail} ${visual.thumbnailWidth}w, ${visual.image} ${visual.width}w`
    : undefined;
  return <img src={visual.image} srcSet={srcSet} sizes={srcSet ? sizes : undefined} alt={alt}
    width={visual.width} height={visual.height} loading="lazy" decoding="async" onError={() => setFailed(true)} />;
}

export function CatalogVisual({ source, compact = false, sizes }: { source: SourceReference; compact?: boolean; sizes?: string }) {
  const visual = catalogVisual(source);
  return <div className={`catalog-visual ${compact ? "is-compact" : ""}`} data-track={visual.track}>
    <CatalogArtwork key={visual.image} visual={visual} sizes={sizes ?? (compact ? "64px" : "132px")} alt={visual.alt ?? visual.categoryTitle} />
  </div>;
}

/** A saved plan's exact goal artwork, with the same sharp assets and fallback as source cards. */
export function PlanGoalVisual({ goalId }: { goalId: string }) {
  const visual = catalogVisualForGoal(goalId);
  return <div className="catalog-visual" data-track={visual?.track ?? "development"}>
    <CatalogArtwork key={visual?.image ?? goalId} visual={visual ?? { emoji: "🌱" }}
      sizes="(max-width: 650px) 82px, 136px" alt={visual?.alt ?? ""} />
  </div>;
}

export function DurationBadge({ seconds }: { seconds: number }) {
  return <span>{seconds < 60 ? "Under a minute" : `About ${Math.ceil(seconds / 60)} min`}</span>;
}

/** Public, canonical child-facing goal wording only; no parent notes or private data. */
export function KidGoalReference({ goalId }: { goalId: string }) {
  const goal = byGoalId[goalId];
  if (!goal) return null;
  return <aside className="kid-goal-reference" aria-label="Your goal">
    <CatalogArtwork key={goal.image} visual={goal} sizes="88px" alt={goal.alt} />
    <div><span>My goal</span><b>{goal.title}</b><p>{goal.description}</p></div>
  </aside>;
}
